'use strict';
const MW_ACTIONS={"scan": "Clients suchen", "hook": "Auswahl hooken", "unhook": "Auswahl unhooken", "interact": "X an Clients", "sync": "XYZ synchronisieren", "quest_tp": "Navmap Quest-TP · aktiver Client", "quest_all": "Navmap Quest-TP · alle", "speed_toggle": "Geschwindigkeit umschalten", "combat_toggle": "Auto-Combat umschalten", "dialogue_toggle": "Auto-Dialog umschalten", "questing_toggle": "Auto-Questing umschalten", "sigil_toggle": "Auto-Sigil umschalten", "freecam": "Freecam umschalten", "camera_tp": "Zur Freecam teleportieren", "run_script": "Skript starten", "stop": "Alle Automatiken stoppen", "forward": "W an Auswahl"};
const MW_DEFAULTS={"global_hotkeys": true, "poll_seconds": 2, "key_seconds": 0.2, "bindings": {"scan": "Ctrl+Alt+S", "hook": "Ctrl+Alt+H", "unhook": "Ctrl+Alt+U", "interact": "X", "sync": "F8", "quest_tp": "F7", "quest_all": "F6", "speed_toggle": "F5", "combat_toggle": "9", "dialogue_toggle": "F4", "questing_toggle": "F3", "sigil_toggle": "F2", "freecam": "F1", "camera_tp": "Shift+F1", "run_script": "Ctrl+Alt+R", "stop": "Ctrl+Alt+F8", "forward": "Ctrl+Alt+W"}, "movement": {"scope": "all", "speed_percent": 100, "navmap_target": "auto", "navmap_timeout": 20, "freecam_scope": "leader"}, "automation": {"interval": 1, "max_minutes": 15, "combat_rules": "any<aoe>@enemy\npass", "combat_pass": true, "quest_accept": true, "quest_forward": false, "quest_distance": 150, "sigil_rejoin": true, "sigil_confirm": true, "sigil_cooldown": 5}};
const MW_UI_DEFAULTS={accent:'purple',compact:false,reduced_motion:false,notifications:true,log_limit:250};
function mwCombo(value){if(typeof value!=='string')throw Error('Shortcut muss Text sein.');if(!value.trim())return '';const parts=value.replace(/\s/g,'').toUpperCase().replace(/NINE/g,'9').split('+'),key=parts.pop(),mods=new Set(parts);if(mods.size!==parts.length||parts.some(p=>!['CTRL','ALT','SHIFT'].includes(p))||!/^([A-Z0-9]|F([1-9]|10|11)|SPACE|ENTER|ESC|TAB)$/.test(key)||!mods.size&&!['X','9'].includes(key)&&!/^F([1-9]|10|11)$/.test(key))throw Error('Nutze X, 9, F1–F11 oder eine Kombination mit Ctrl/Alt/Shift.');return [...['CTRL','ALT','SHIFT'].filter(p=>mods.has(p)).map(p=>p[0]+p.slice(1).toLowerCase()),key].join('+');}
function mwCombatRules(source){if(typeof source!=='string'||source.length>4000)throw Error('Kampfregeln: maximal 4000 Zeichen.');const rows=source.split(/\r?\n/).map(l=>l.trim()).filter(l=>l&&!l.startsWith('#'));if(!rows.length||rows.length>30)throw Error('1–30 Kampfregeln erforderlich.');for(const row of rows){if(row==='pass')continue;const m=row.match(/^([^@\n]{1,180})@(self|enemy|none)$/);if(!m||m[1].includes('<')&&m[1]!=='any<aoe>')throw Error('Kampfregel: Kartenname@self/enemy/none, any<aoe>@enemy oder pass.');}return source;}
function mwValidate(value){if(!value||Object.keys(value).sort().join()!==Object.keys(MW_DEFAULTS).sort().join()||typeof value.global_hotkeys!=='boolean')throw Error('Ungültiges Bridge-Settings-Format.');const range=(n,lo,hi)=>{if(typeof n!=='number'||!Number.isFinite(n)||n<lo||n>hi)throw Error(`Zahl: ${lo} bis ${hi}.`);};range(value.poll_seconds,.5,10);range(value.key_seconds,.01,5);if(!value.bindings||Object.keys(value.bindings).sort().join()!==Object.keys(MW_ACTIONS).sort().join())throw Error('Ungültige Shortcut-Aktionen.');const bindings=Object.fromEntries(Object.keys(MW_ACTIONS).map(a=>[a,mwCombo(value.bindings[a])])),used=Object.values(bindings).filter(Boolean);if(new Set(used).size!==used.length)throw Error('Jeder Shortcut darf nur einmal vergeben werden.');const m=value.movement,a=value.automation;for(const [key,obj] of [['movement',m],['automation',a]])if(!obj||Object.keys(obj).sort().join()!==Object.keys(MW_DEFAULTS[key]).sort().join())throw Error('Ungültige '+key+'-Settings.');if(!['all','selected'].includes(m.scope)||!['auto','own','leader'].includes(m.navmap_target)||!['leader','selected'].includes(m.freecam_scope))throw Error('Ungültiger Movement-Modus.');range(m.speed_percent,0,300);if(!Number.isInteger(m.speed_percent))throw Error('Geschwindigkeit muss ganzzahlig sein.');range(m.navmap_timeout,3,25);range(a.interval,.5,5);range(a.max_minutes,1,60);range(a.quest_distance,25,1000);range(a.sigil_cooldown,2,60);for(const k of ['combat_pass','quest_accept','quest_forward','sigil_rejoin','sigil_confirm'])if(typeof a[k]!=='boolean')throw Error(k+' muss boolesch sein.');mwCombatRules(a.combat_rules);return {...value,bindings,movement:{...m},automation:{...a}};}
function mwMigrate(value){const result=JSON.parse(JSON.stringify(MW_DEFAULTS));if(value&&typeof value==='object')for(const k of Object.keys(result)){if(!(k in value))continue;if(result[k]&&typeof result[k]==='object')Object.assign(result[k],Object.fromEntries(Object.entries(value[k]||{}).filter(([n])=>n in result[k])));else result[k]=value[k];}return mwValidate(result);}
function mwUi(value){if(!value||Object.keys(value).sort().join()!==Object.keys(MW_UI_DEFAULTS).sort().join()||!['purple','teal','gold'].includes(value.accent)||['compact','reduced_motion','notifications'].some(k=>typeof value[k]!=='boolean')||!Number.isInteger(value.log_limit)||value.log_limit<50||value.log_limit>1000)throw Error('Ungültige Anzeige-Einstellungen.');return {...value};}
if(typeof module!=='undefined')module.exports={mwCombo,mwValidate,mwUi,mwMigrate,mwCombatRules,MW_DEFAULTS,MW_UI_DEFAULTS};
function createMythicSettings(api){
 const $=id=>document.getElementById(id);let config,ui,status={supported:false,active:[],errors:{}},recording=null,context='',contextTimer;
 try{config=mwMigrate(JSON.parse(localStorage.getItem('mythic-settings-v3')||localStorage.getItem('mythic-settings-v2')));}catch{config=mwValidate(MW_DEFAULTS);}
 try{ui=mwUi(JSON.parse(localStorage.getItem('mythic-ui-v2')));}catch{ui={...MW_UI_DEFAULTS};}
 const storage=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{api.toast('Speicher nicht verfügbar. Konfiguration exportieren.');}};
 function apply(){document.body.dataset.accent=ui.accent;document.body.classList.toggle('compact',ui.compact);document.body.classList.toggle('reduce-motion',ui.reduced_motion);$('key-seconds').value=config.key_seconds;api.applyUi(ui);}
 function statusText(){const messages=Object.entries(status.errors||{}).map(([a,e])=>`${MW_ACTIONS[a]||a}: ${e}`);$('shortcut-status').textContent=recording?'Taste jetzt drücken · Escape bricht ab.':!api.connected()?'Browser-Shortcuts bereit. Spiel-Shortcuts brauchen die neue Beta-Bridge.':config.global_hotkeys?(status.supported?`${status.active.length} Shortcuts im fokussierten Spiel aktiv. ${messages.join(' ')}${!status.active.length?' Wizard101 fokussieren und Clients hooken.':''}`:'Globale Shortcuts sind auf Windows verfügbar. Im Browser funktionieren sie hier.'): 'Browser-Shortcuts aktiv, globale Shortcuts ausgeschaltet.';}
 function draw(){for(const [key,value] of Object.entries(config))if(!['bindings','movement','automation'].includes(key)){$('setting-'+key)[typeof value==='boolean'?'checked':'value']=value;}for(const group of ['movement','automation'])for(const [key,value] of Object.entries(config[group]))$('setting-'+group+'-'+key)[typeof value==='boolean'?'checked':'value']=value;for(const [key,value] of Object.entries(ui))$('setting-'+key)[typeof value==='boolean'?'checked':'value']=value;$('shortcut-rows').innerHTML=Object.entries(MW_ACTIONS).map(([a,label])=>`<div class="shortcut-row"><label for="binding-${a}">${label}<small>${a==='scan'?'Alle geöffneten Clients':a==='stop'?'Skript & alle Automatiken':a==='run_script'?'Inhalt des Skript-Editors':['hook','unhook','forward'].includes(a)?'Ausgewählte Clients':'Movement-Scope und aktiver/Leader-Client'}</small></label><input id="binding-${a}" data-binding="${a}" value="${config.bindings[a]}" placeholder="Deaktiviert" autocomplete="off" spellcheck="false" aria-label="Shortcut für ${label}"><button class="button compact" data-record="${a}">Aufnehmen</button></div>`).join('');document.querySelectorAll('[data-record]').forEach(b=>b.onclick=async()=>{try{await finishRecording();if(api.connected())await api.command('pause_hotkeys',{paused:true});recording=b.dataset.record;$('binding-'+recording).focus();statusText();}catch(e){api.toast(e.message);}});statusText();}
 async function finishRecording(){if(!recording)return;recording=null;if(api.connected())await api.command('pause_hotkeys',{paused:false});statusText();}
 function read(){const next={global_hotkeys:$('setting-global_hotkeys').checked,poll_seconds:Number($('setting-poll_seconds').value),key_seconds:Number($('setting-key_seconds').value),bindings:Object.fromEntries(Object.keys(MW_ACTIONS).map(a=>[a,$('binding-'+a).value]))};const nextUi=Object.fromEntries(Object.keys(MW_UI_DEFAULTS).map(k=>[k,typeof MW_UI_DEFAULTS[k]==='boolean'?$('setting-'+k).checked:k==='log_limit'?Number($('setting-'+k).value):$('setting-'+k).value]));for(const group of ['movement','automation'])next[group]=Object.fromEntries(Object.entries(MW_DEFAULTS[group]).map(([key,value])=>[key,typeof value==='boolean'?$('setting-'+group+'-'+key).checked:typeof value==='number'?Number($('setting-'+group+'-'+key).value):$('setting-'+group+'-'+key).value]));return {bridge:mwValidate(next),ui:mwUi(nextUi)};}
 async function save(next){await finishRecording();if(api.connected()){const result=await api.command('set_settings',{settings:next.bridge});status=result.hotkeys;config=mwValidate(result.settings);}else config=next.bridge;ui=next.ui;storage('mythic-settings-v3',config);storage('mythic-ui-v2',ui);apply();draw();api.toast(api.connected()?'Settings gespeichert · Bridge und Browser aktualisiert.':'Settings im Browser gespeichert. Beim Koppeln an die Bridge übertragen.');}
 $('save-settings').onclick=async()=>{try{await save(read());}catch(e){api.toast(e.message);}};
 $('reset-settings').onclick=async()=>{try{await save({bridge:mwValidate(MW_DEFAULTS),ui:{...MW_UI_DEFAULTS}});}catch(e){api.toast(e.message);}};
 $('export-settings').onclick=()=>{try{const value=read();api.download('MythicWalker_Settings.json',JSON.stringify({version:3,...value},null,2),'application/json');}catch(e){api.toast(e.message);}};
 $('import-settings').onclick=()=>$('settings-file').click();$('settings-file').onchange=async()=>{try{const file=$('settings-file').files[0];if(!file)return;if(file.size>20000)throw Error('Settings-Datei zu groß.');const value=JSON.parse(await file.text());if(![2,3].includes(value.version))throw Error('Settings-Version nicht unterstützt.');await save({bridge:mwMigrate(value.bridge),ui:mwUi(value.ui)});}catch(e){api.toast(e.message);}finally{$('settings-file').value='';}};
 document.addEventListener('keydown',async e=>{if(recording){e.preventDefault();e.stopImmediatePropagation();if(e.key==='Escape'){await finishRecording();return;}if(['Control','Alt','Shift','Meta'].includes(e.key))return;try{const combo=mwCombo([e.ctrlKey?'Ctrl':'',e.altKey?'Alt':'',e.shiftKey?'Shift':'',e.key===' '?'SPACE':e.key==='Escape'?'ESC':e.key.toUpperCase()].filter(Boolean).join('+'));$('binding-'+recording).value=combo;await finishRecording();}catch(err){api.toast(err.message);}return;}if(e.repeat||e.isComposing||e.metaKey||e.target.closest('input,textarea,select,[contenteditable="true"]')||document.querySelector('dialog[open]'))return;let combo;try{combo=mwCombo([e.ctrlKey?'Ctrl':'',e.altKey?'Alt':'',e.shiftKey?'Shift':'',e.key===' '?'SPACE':e.key==='Escape'?'ESC':e.key.toUpperCase()].filter(Boolean).join('+'));}catch{return;}const action=Object.keys(config.bindings).find(a=>config.bindings[a]===combo);if(!action)return;e.preventDefault();if(api.connected()&&status.active.includes(action))return;api.shortcut(action);},true);
 window.addEventListener('blur',()=>{finishRecording().catch(()=>{});});window.addEventListener('hashchange',()=>{finishRecording().catch(()=>{});});document.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>finishRecording().catch(()=>{})));
 apply();draw();
 return {value:()=>config,ui:()=>ui,keySeconds:()=>config.key_seconds,hotkeys(value){status=value;statusText();},context(){if(!api.connected())return;const value=JSON.stringify(api.context());if(value===context)return;clearTimeout(contextTimer);contextTimer=setTimeout(async()=>{if(!api.connected())return;try{await api.command('shortcut_context',JSON.parse(value));context=value;}catch(e){api.log(e.message,'error');}},100);},async paired(){context='';try{const value=await api.command('set_settings',{settings:config});status=value.hotkeys;config=mwValidate(value.settings);draw();this.context();}catch(e){api.log('Settings benötigen die neue Beta-Bridge: '+e.message,'warning');}},closed(){context='';status={supported:false,active:[],errors:{}};recording=null;statusText();},leave(){finishRecording().catch(()=>{});}};
}
